import { Client } from 'pg';
import axios from 'axios';

interface PostgresProductEvent {
  id: string;
  user_id: string;
  product_id: string;
  event_type: string;
  timestamp: Date;
  session_id?: string;
  properties?: any;
}

interface MooseProductEvent {
  id: string;
  userId: string;
  productId: string;
  eventType: "view" | "add_to_cart" | "purchase";
  timestamp: Date;
  sessionId?: string;
  properties?: Record<string, any>;
}

const MOOSE_INGEST_URL = 'http://localhost:4000/ingest/ProductEvent';

// Postgres connection configuration
const pgConfig = {
  host: process.env.PG_HOST || 'localhost',
  port: parseInt(process.env.PG_PORT || '5432'),
  database: process.env.PG_DATABASE || 'analytics',
  user: process.env.PG_USER || 'postgres',
  password: process.env.PG_PASSWORD || 'password',
};

async function ingestFromPostgres() {
  const client = new Client(pgConfig);

  try {
    console.log('Connecting to Postgres...');
    await client.connect();

    console.log('Fetching product events...');
    const result = await client.query(`
      SELECT
        id,
        user_id,
        product_id,
        event_type,
        timestamp,
        session_id,
        properties
      FROM raw.product_events
      ORDER BY timestamp DESC
      LIMIT 1000
    `);

    console.log(`Found ${result.rows.length} events to ingest`);

    // Transform and send events to Moose
    let successCount = 0;
    let errorCount = 0;

    for (const row of result.rows) {
      try {
        const mooseEvent: MooseProductEvent = {
          id: row.id,
          userId: row.user_id,
          productId: row.product_id,
          eventType: mapEventType(row.event_type),
          timestamp: new Date(row.timestamp),
          sessionId: row.session_id,
          properties: row.properties || {}
        };

        // Send to Moose ingestion API
        await axios.post(MOOSE_INGEST_URL, mooseEvent, {
          headers: {
            'Content-Type': 'application/json'
          },
          timeout: 5000
        });

        successCount++;

        if (successCount % 100 === 0) {
          console.log(`Ingested ${successCount} events...`);
        }
      } catch (error) {
        errorCount++;
        console.error(`Error ingesting event ${row.id}:`, error.message);
      }
    }

    console.log(`\nIngestion complete:`);
    console.log(`- Successfully ingested: ${successCount} events`);
    console.log(`- Errors: ${errorCount} events`);

  } catch (error) {
    console.error('Error during ingestion:', error);
    throw error;
  } finally {
    await client.end();
  }
}

function mapEventType(pgEventType: string): "view" | "add_to_cart" | "purchase" {
  switch (pgEventType.toLowerCase()) {
    case 'view':
    case 'page_view':
    case 'product_view':
      return 'view';
    case 'add_to_cart':
    case 'cart_add':
    case 'add_cart':
      return 'add_to_cart';
    case 'purchase':
    case 'buy':
    case 'order':
    case 'checkout':
      return 'purchase';
    default:
      console.warn(`Unknown event type: ${pgEventType}, defaulting to 'view'`);
      return 'view';
  }
}

// Run the ingestion if this file is executed directly
if (require.main === module) {
  ingestFromPostgres()
    .then(() => {
      console.log('Ingestion completed successfully');
      process.exit(0);
    })
    .catch((error) => {
      console.error('Ingestion failed:', error);
      process.exit(1);
    });
}

export { ingestFromPostgres };

