import { IngestPipeline, Key, MaterializedView, sql } from "@514labs/moose-lib";

// Product Event data model for analytics
export interface ProductEvent {
  id: Key<string>;
  userId: string;
  productId: string;
  eventType: "view" | "add_to_cart" | "purchase";
  timestamp: Date;
  sessionId?: string;
  properties?: Record<string, any>; // JSONB field from Postgres - includes price for purchases
}

// Ingest pipeline for product events - creates table, stream, and API endpoint
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: { orderByFields: ["userId", "timestamp"] },
  stream: true,
  ingestApi: true,
});

// Aggregation Views

// 1. Top Products by Purchase Count with Revenue
export interface TopProductsSummary {
  productId: string;
  purchaseCount: number;
  totalRevenue: number;
  avgRevenue: number;
  lastPurchase: Date;
}

const productEventsTable = ProductEventPipeline.table;
if (!productEventsTable) {
  throw new Error("ProductEvent table not configured in pipeline");
}

export const topProductsMV = new MaterializedView<TopProductsSummary>({
  tableName: "TopProductsSummary",
  materializedViewName: "TopProducts_MV",
  orderByFields: ["purchaseCount", "productId"],
  selectTables: [productEventsTable],
  selectStatement: sql`
    SELECT
      productId,
      count() AS purchaseCount,
      sum(JSONExtractFloat(properties, 'price')) AS totalRevenue,
      avg(JSONExtractFloat(properties, 'price')) AS avgRevenue,
      max(timestamp) AS lastPurchase
    FROM ${productEventsTable}
    WHERE eventType = 'purchase'
    GROUP BY productId
  `,
});

// 2. Conversion Funnel Analysis
export interface ConversionFunnelSummary {
  productId: string;
  viewCount: number;
  cartCount: number;
  purchaseCount: number;
  viewToCartRate: number;
  cartToPurchaseRate: number;
  overallConversionRate: number;
}

export const conversionFunnelMV = new MaterializedView<ConversionFunnelSummary>({
  tableName: "ConversionFunnelSummary",
  materializedViewName: "ConversionFunnel_MV",
  orderByFields: ["overallConversionRate", "productId"],
  selectTables: [productEventsTable],
  selectStatement: sql`
    SELECT
      productId,
      countIf(eventType = 'view') AS viewCount,
      countIf(eventType = 'add_to_cart') AS cartCount,
      countIf(eventType = 'purchase') AS purchaseCount,
      if(viewCount > 0, cartCount / viewCount, 0) AS viewToCartRate,
      if(cartCount > 0, purchaseCount / cartCount, 0) AS cartToPurchaseRate,
      if(viewCount > 0, purchaseCount / viewCount, 0) AS overallConversionRate
    FROM ${productEventsTable}
    GROUP BY productId
    HAVING viewCount > 0
  `,
});

// 3. Hourly Activity Breakdown
export interface HourlyActivitySummary {
  activityHour: Date;
  viewCount: number;
  cartCount: number;
  purchaseCount: number;
  totalRevenue: number;
  uniqueUsers: number;
  uniqueProducts: number;
}

export const hourlyActivityMV = new MaterializedView<HourlyActivitySummary>({
  tableName: "HourlyActivitySummary",
  materializedViewName: "HourlyActivity_MV",
  orderByFields: ["activityHour"],
  selectTables: [productEventsTable],
  selectStatement: sql`
    SELECT
      toStartOfHour(timestamp) AS activityHour,
      countIf(eventType = 'view') AS viewCount,
      countIf(eventType = 'add_to_cart') AS cartCount,
      countIf(eventType = 'purchase') AS purchaseCount,
      sumIf(JSONExtractFloat(properties, 'price'), eventType = 'purchase') AS totalRevenue,
      uniq(userId) AS uniqueUsers,
      uniq(productId) AS uniqueProducts
    FROM ${productEventsTable}
    GROUP BY activityHour
  `,
});

