// Conversion funnel analysis
app.get('/api/funnel', async (req, res) => {
  try {
    const query = `
      SELECT
        productId,
        viewCount,
        cartCount,
        purchaseCount,
        viewToCartRate,
        cartToPurchaseRate,
        overallConversionRate
      FROM local.ConversionFunnelSummary
      ORDER BY overallConversionRate DESC, viewCount DESC
      LIMIT 20
    `;

    const result = await clickhouse.query({
      query: query,
      format: 'JSONEachRow',
    });

    const data = await result.json();

    // Calculate overall funnel metrics
    const totalViews = data.reduce((sum, row) => sum + (row.viewCount || 0), 0);
    const totalCarts = data.reduce((sum, row) => sum + (row.cartCount || 0), 0);
    const totalPurchases = data.reduce((sum, row) => sum + (row.purchaseCount || 0), 0);

    const overallMetrics = {
      totalViews,
      totalCarts,
      totalPurchases,
      overallViewToCartRate: totalViews > 0 ? totalCarts / totalViews : 0,
      overallCartToPurchaseRate: totalCarts > 0 ? totalPurchases / totalCarts : 0,
      overallConversionRate: totalViews > 0 ? totalPurchases / totalViews : 0
    };

    res.json({
      success: true,
      data: data,
      overallMetrics: overallMetrics,
      metadata: {
        count: data.length,
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    console.error('Error fetching funnel data:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to fetch conversion funnel data',
      message: error.message
    });
  }
});

// Hourly activity breakdown
app.get('/api/hourly', async (req, res) => {
  try {
    const hoursBack = parseInt(req.query.hours as string) || 24;

    const query = `
      SELECT
        activityHour,
        viewCount,
        cartCount,
        purchaseCount,
        totalRevenue,
        uniqueUsers,
        uniqueProducts
      FROM local.HourlyActivitySummary
      WHERE activityHour >= now() - INTERVAL ${hoursBack} HOUR
      ORDER BY activityHour DESC
    `;

    const result = await clickhouse.query({
      query: query,
      format: 'JSONEachRow',
    });

    const data = await result.json();

    // Calculate summary statistics
    const summary = {
      totalViews: data.reduce((sum, row) => sum + (row.viewCount || 0), 0),
      totalCarts: data.reduce((sum, row) => sum + (row.cartCount || 0), 0),
      totalPurchases: data.reduce((sum, row) => sum + (row.purchaseCount || 0), 0),
      totalRevenue: data.reduce((sum, row) => sum + (row.totalRevenue || 0), 0),
      peakHour: data.reduce((peak, row) =>
        (row.viewCount + row.cartCount + row.purchaseCount) >
        (peak.viewCount + peak.cartCount + peak.purchaseCount) ? row : peak,
        data[0] || {}
      )
    };

    res.json({
      success: true,
      data: data,
      summary: summary,
      metadata: {
        count: data.length,
        hoursBack: hoursBack,
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    console.error('Error fetching hourly activity:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to fetch hourly activity data',
      message: error.message
    });
  }
});

